"summary": "Dr. Skull'ın temelleri 1983'te Ankara Fen Lisesi öğrencileri Murat Baştepe, Murat Ersöz ve Alper Yarangümeli tarafından atıldı. Milliyet Liselerarası Müzik Yarışması'nda ikinci oldular. İlk konserlerine Skull adıyla çıktılar; üyelerin hepsi tıp fakültesini kazanınca ad Dr. Skull oldu. Ada Müzik'ten \"Wory Zover\" (1990) ve \"Rools 4 Fools\" (1992) çıktı. Baştepe ABD'ye gidince yerine Serdar Tuksal geldi; grup 1994'te Kent Müzik'ten tamamen Türkçe tek albümü \"Hershey Yolunda!?\"yı yayımladı ve aynı yıl Harbiye Açıkhava'da Die Toten Hosen ile aynı sahneyi paylaştı. 2017'de yeniden bir araya geldiler; 2019'da Ankara'da verdikleri veda konseri canlı albüm olarak yayımlandı.",
