"genres": "Rap",
"active": "1995–günümüz",
"summary": "Asıl adı Ercüment Ergün olan Erci E., Türk göçmen işçi bir ailenin çocuğu olarak Berlin'de doğan Türk-Alman rapçi, şarkıcı ve söz yazarıdır. 1995'te Karakan ve Da Crime Posse ile birlikte Türkçe rapin öncü projesi Cartel'i oluşturdu. Cartel dağıldıktan sonra solo albümünü ilk çıkaran isim oldu; Almanya'da \"Türk Olduğum İçin\" teklisini yayımladı, 1998'de Peter Maffay ile ortak çalıştı. Yıllar sonra \"Berlin-İstanbul\" adlı bir EP yayımladı.",
